use std::{env,fs,path::PathBuf,process::{Command,Output},thread::sleep,time::{Duration,Instant}};
const PACKAGE:&str="com.ofairyo.gridtimer";
const MARKER:&str="TenRateEmulatorProbe20261103";
#[derive(Clone)]
struct Node{text:String,desc:String,class:String,x:i32,y:i32,w:i32,h:i32}
struct Case{name:String,status:&'static str,evidence:String}
struct Probe{root:PathBuf,cases:Vec<Case>,fatal:bool,shots:usize}
fn adb(args:&[&str])->Result<Output,String>{Command::new("adb").args(args).output().map_err(|e|e.to_string())}
fn cmd(args:&[&str])->Result<String,String>{let o=adb(args)?;if !o.status.success(){return Err(format!("adb {:?}: {}",args,String::from_utf8_lossy(&o.stderr)))}Ok(String::from_utf8_lossy(&o.stdout).into_owned())}
fn attr(s:&str,k:&str)->String{let key=format!("{k}=\"");s.find(&key).and_then(|a|{let x=&s[a+key.len()..];x.find('"').map(|b|x[..b].to_string())}).unwrap_or_default()}
fn nodes(xml:&str)->Vec<Node>{xml.split("<node ").skip(1).filter_map(|chunk|{let s=chunk.split('>').next()?;let b=attr(s,"bounds");let v:Vec<i32>=b.split(|c:char|!c.is_ascii_digit()&&c!='-').filter(|x|!x.is_empty()).filter_map(|x|x.parse().ok()).collect();if v.len()!=4||v[2]<=v[0]||v[3]<=v[1]{return None}Some(Node{text:attr(s,"text"),desc:attr(s,"content-desc"),class:attr(s,"class"),x:v[0],y:v[1],w:v[2]-v[0],h:v[3]-v[1]})}).collect()}
fn find(xml:&str,labels:&[&str],bottom:bool)->Option<(Node,String)>{let mut out=Vec::new();for n in nodes(xml){for label in labels{if n.w>2&&n.h>2&&(n.text==*label||n.desc==*label||(label.chars().count()>1&&(n.text.contains(label)||n.desc.contains(label)))){out.push((n.clone(),(*label).to_string()));}}}out.sort_by_key(|(n,_)|if bottom{-n.y}else{n.y});out.into_iter().next()}
fn dump()->Result<String,String>{for _ in 0..3{let _=cmd(&["shell","uiautomator","dump","/sdcard/probe.xml"]);if let Ok(s)=cmd(&["exec-out","cat","/sdcard/probe.xml"]){if s.contains("<hierarchy")&&s.contains("<node "){return Ok(s)}}sleep(Duration::from_millis(650))}Err("Accessibility hierarchy unavailable".into())}
fn alive()->bool{cmd(&["shell","pidof",PACKAGE]).map(|s|!s.trim().is_empty()).unwrap_or(false)}
fn tap(n:&Node)->Result<(),String>{let x=(n.x+n.w/2).to_string();let y=(n.y+n.h/2).to_string();cmd(&["shell","input","tap",&x,&y]).map(|_|())}
fn back(){let _=cmd(&["shell","input","keyevent","4"]);sleep(Duration::from_millis(700))}
impl Probe{
fn new(root:PathBuf)->Self{fs::create_dir_all(&root).expect("create evidence directory");Self{root,cases:Vec::new(),fatal:false,shots:0}}
fn record(&mut self,name:&str,status:&'static str,evidence:impl Into<String>){let evidence=evidence.into();println!("[{status}] {name}: {evidence}");self.fatal|=status=="FAIL";self.cases.push(Case{name:name.into(),status,evidence})}
fn shot(&mut self,label:&str)->String{self.shots+=1;let name=format!("{:02}_{}",self.shots,label);let png=self.root.join(format!("{name}.png"));let xml=self.root.join(format!("{name}.xml"));let mut info=Vec::new();if let Ok(o)=adb(&["exec-out","screencap","-p"]){if o.status.success()&&o.stdout.starts_with(b"\x89PNG")&&fs::write(&png,&o.stdout).is_ok(){info.push(format!("screenshot={}",png.display()))}}match dump(){Ok(s)=>{let _=fs::write(&xml,&s);info.push(format!("accessibility_nodes={}",nodes(&s).len()));},Err(e)=>info.push(e)}info.join("; ")}
fn click(&mut self,labels:&[&str],name:&str,bottom:bool)->bool{let before=match dump(){Ok(x)=>x,Err(e)=>{self.record(name,"SKIP",e);return false}};let Some((node,label))=find(&before,labels,bottom)else{self.record(name,"SKIP",format!("labels {:?} unavailable",labels));return false};if let Err(e)=tap(&node){self.record(name,"FAIL",e);return false}sleep(Duration::from_millis(1200));let after=dump().unwrap_or_default();let ok=alive();let evidence=self.shot(name);if !ok{self.record(name,"FAIL",format!("process ended after tap {label}; {evidence}"))}else if !after.is_empty()&&after==before{self.record(name,"WARN",format!("tap {label} did not change accessibility tree; {evidence}"))}else{self.record(name,"PASS",format!("tap {label} with process alive; {evidence}"))}ok}
fn nav(&mut self,labels:&[&str],name:&str)->bool{if self.click(labels,name,true){return true}back();self.click(labels,&format!("{name}_after_back"),true)}
fn swipe(&mut self,name:&str,up:bool){let(a,b)=if up{("1450","490")}else{("490","1450")};let r=cmd(&["shell","input","swipe","540",a,"540",b,"400"]);sleep(Duration::from_millis(750));let evidence=self.shot(name);match r{Err(e)=>self.record(name,"FAIL",e),Ok(_)=>self.record(name,if alive(){"PASS"}else{"FAIL"},format!("gesture executed; {evidence}"))}}
fn editor(&mut self,name:&str){let xml=match dump(){Ok(s)=>s,Err(e)=>{self.record(name,"SKIP",e);return}};let field=nodes(&xml).into_iter().find(|n|n.class.contains("EditText")&&n.w>30&&n.h>10);let Some(field)=field else{self.record(name,"SKIP","no editable field visible");return};if let Err(e)=tap(&field){self.record(name,"FAIL",e);return}let input=cmd(&["shell","input","text",MARKER]);sleep(Duration::from_millis(800));let ui=dump().unwrap_or_default();let evidence=self.shot(name);match input{Err(e)=>self.record(name,"FAIL",e),Ok(_)=>self.record(name,if ui.contains(MARKER){"PASS"}else{"WARN"},format!("typed marker; visible={}; {evidence}",ui.contains(MARKER)))}back()}
fn notes(&mut self){if !self.nav(&["便签","笔记","Notes","Sticky"],"notes_open"){return}let shot=self.shot("notes_first");self.record("notes_display","PASS",shot);self.swipe("notes_swipe",true);if self.click(&["新建便签","添加便签","新建笔记","创建便签","新建","+"],"notes_create",false){self.editor("notes_input");back();let _=self.shot("notes_exit");}}
fn restart(&mut self){let _=cmd(&["shell","am","force-stop",PACKAGE]);sleep(Duration::from_millis(800));let r=cmd(&["shell","am","start","-W","-n","com.ofairyo.gridtimer/.MainActivity"]);sleep(Duration::from_secs(4));let shot=self.shot("process_restart");match r{Err(e)=>self.record("process_restart","FAIL",e),Ok(_)=>self.record("process_restart",if alive(){"PASS"}else{"FAIL"},shot)}}
fn logs(&mut self){let logs=cmd(&["logcat","-d","-v","time"]).unwrap_or_default();let _=fs::write(self.root.join("logcat.txt"),&logs);let relevant=logs.contains("Process: com.ofairyo.gridtimer")||logs.contains("ANR in com.ofairyo.gridtimer")||logs.lines().any(|l|l.contains("Fatal signal")&&l.contains(PACKAGE));self.record("crash_anr_scan",if relevant{"FAIL"}else{"PASS"},if relevant{"app crash or ANR indicator in logcat.txt"}else{"no app process crash or ANR identifier found"})}
fn finish(&self){let mut s=String::from("# TenRate Android Emulator Audit\n\nFresh emulator, no account login or real data.\n\n| Case | Result | Evidence |\n|---|---|---|\n");for c in &self.cases{s.push_str(&format!("| {} | {} | {} |\n",c.name,c.status,c.evidence.replace('|',"/").replace('\n'," ")))}s.push_str("\nLimitations: attempted taps are not proof of expected screen behavior. SKIP is not a product defect. Offline UI only; no private data, third-party AI, signed-in sync, OEM APIs or long-duration scenarios. Review screenshots, XML and logcat.\n");fs::write(self.root.join("report.md"),s).expect("write report")}
}
fn main(){let root=env::args().nth(1).map(PathBuf::from).unwrap_or_else(||"emulator_evidence".into());let mut p=Probe::new(root);let sdk=cmd(&["shell","getprop","ro.build.version.sdk"]).unwrap_or_default();let devices=cmd(&["devices"]).unwrap_or_default();p.record("emulator",if devices.contains("emulator-"){"PASS"}else{"FAIL"},format!("sdk={}, devices={}",sdk.trim(),devices.trim()));let _=cmd(&["logcat","-c"]);let _=cmd(&["shell","pm","clear",PACKAGE]);let start=Instant::now();let launch=cmd(&["shell","am","start","-W","-n","com.ofairyo.gridtimer/.MainActivity"]);sleep(Duration::from_secs(6));let first=p.shot("cold_start");match launch{Err(e)=>p.record("cold_start","FAIL",e),Ok(_)=>p.record("cold_start",if alive(){"PASS"}else{"FAIL"},format!("elapsed={}ms; {first}",start.elapsed().as_millis()))}p.swipe("home_swipe_up",true);p.swipe("home_swipe_down",false);p.nav(&["计时","专注","Timer","Focus"],"timer_open");p.notes();if p.nav(&["知识","知识库","Knowledge"],"knowledge_open"){p.swipe("knowledge_swipe",true);p.click(&["新建页面","创建页面","添加页面","新建"],"knowledge_create",false);back()}if p.nav(&["财务","记账","Finance"],"finance_open"){p.swipe("finance_swipe",true)}if p.nav(&["画布","Canvas"],"canvas_open"){p.swipe("canvas_swipe",true)}if p.nav(&["法律","法务","Legal"],"legal_open"){p.swipe("legal_swipe",true)}if p.nav(&["Agent","智能体","代理"],"agent_open"){p.swipe("agent_swipe",true)}if p.nav(&["我的","设置","Me","Profile"],"my_open"){p.swipe("my_swipe",true)}p.restart();p.logs();p.finish();if p.fatal{std::process::exit(1)}}
